import '../src/tokens/tokens.css';
import './preview.css';
import { setCustomElementsManifest } from '@storybook/web-components-vite';
import type { Preview } from '@storybook/web-components-vite';

// Generated by `npm run manifest`; powers the props/slots/parts tables in Docs.
// Relative on purpose: the published docs live under /halftone/, not at the site root.
const manifest = await fetch('custom-elements.json').then((r) => r.json()).catch(() => undefined);
if (manifest) setCustomElementsManifest(manifest);

const preview: Preview = {
  parameters: { backgrounds: { disabled: true }, layout: 'centered' },
  globalTypes: {
    theme: {
      description: 'Halftone theme',
      toolbar: {
        title: 'Theme',
        icon: 'circlehollow',
        items: [
          { value: 'light', title: 'Light' },
          { value: 'dark', title: 'Dark' },
        ],
        dynamicTitle: true,
      },
    },
  },
  initialGlobals: { theme: 'light' },
  decorators: [
    (story, ctx) => {
      document.documentElement.dataset.theme = ctx.globals.theme ?? 'light';
      return story();
    },
  ],
};
export default preview;
